import unittest

from hourglass.models import Span
from hourglass.rounding import round_labels


class RoundLabelTests(unittest.TestCase):
    def test_label_format(self):
        spans = [Span(540, 1035)]
        self.assertEqual(
            round_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_rounds_to_nearest_step(self):
        spans = [Span(542, 1028)]
        self.assertEqual(
            round_labels(spans, 15), ["09:00-17:15 (8h 15m)"]
        )

    def test_empty_list(self):
        self.assertEqual(round_labels([], 5), [])

    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(0, 60)], step)


if __name__ == "__main__":
    unittest.main()
